{
  "implementation": "from collections import deque

def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']

    # Build lookup, children, child count
    node_map = {}
    children = {}
    child_count = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = n
        children[nid] = []
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])
    for nid in children:
        child_count[nid] = len(children[nid])

    removed = set()

    # Initial queue: sort by depth descending, then id ascending
    all_ids = [n['id'] for n in nodes]
    all_ids.sort(key=lambda x: (-node_map[x]['depth'], x))
    queue = deque(all_ids)

    visit_order = []

    while queue:
        nid = queue.popleft()
        visit_order.append(nid)
        if nid in removed:
            continue
        node = node_map[nid]
        if node['removable'] and node['utility'] <= threshold and child_count[nid] == 0:
            # Remove this node
            removed.add(nid)
            parent = node['parent']
            if parent is not None and parent not in removed:
                # Decrement child count of parent
                child_count[parent] -= 1
                queue.append(parent)

    retained = [n['id'] for n in nodes if n['id'] not in removed]
    return {
        'retained_node_ids': retained,
        'visit_order': visit_order
    }"
}
